const waitForMongo=async(uri,retries=30,delay=2000)=>{
 for(let i=0;i<retries;i++){
  try{
   await mongoose.connect(uri);
   console.log("MongoDB connected");
   return;
  }catch(err){
   console.log(`Waiting for MongoDB... attempt ${i+1}/${retries}`);
   if(i===retries-1)throw err;
   await new Promise(resolve=>setTimeout(resolve,delay));
  }
 }
};

let businessConnection=null;

const startApp=async()=>{
 if(!process.env.MONGO_URI)throw new Error("MONGO_URI is not defined");

 await waitForMongo(process.env.MONGO_URI);

 if(process.env.MONGO_BUSINESS_URI){
  businessConnection=await mongoose.createConnection(process.env.MONGO_BUSINESS_URI).asPromise();
  console.log("Business MongoDB connected");
 }

 registerReminderSocket(io);
 startReminderCron(io);

 server.listen(PORT,()=>{
  console.log(`Backend running on port ${PORT}`);
 });
};

await startApp();

const shutdown=async(signal="SIGTERM")=>{
 if(isShuttingDown)return;
 isShuttingDown=true;

 try{
  console.log(`Received ${signal}. Shutting down...`);

  if(server)await new Promise(resolve=>server.close(resolve));
  if(mongoose.connection.readyState===1)await mongoose.connection.close();
  if(businessConnection&&businessConnection.readyState===1)await businessConnection.close();



  process.exit(0);
 }catch(err){
  console.error(err);
  process.exit(1);
 }
};

process.on("SIGINT",()=>shutdown("SIGINT"));
process.on("SIGTERM",()=>shutdown("SIGTERM"));

// backend/services/reminderEmailService.js
import nodemailer from "nodemailer";

const smtpHost=(process.env.SMTP_HOST||"").trim();
const smtpPort=Number(process.env.SMTP_PORT||0);
const smtpSecure=String(process.env.SMTP_SECURE||"false").toLowerCase()==="true";
const smtpUser=(process.env.SMTP_USER||"").trim();
const smtpPass=(process.env.SMTP_PASS||"").trim();
const smtpFrom=(process.env.SMTP_FROM||"").trim();

const isEmailConfigured=Boolean(
 smtpHost&&smtpPort&&smtpFrom&&smtpUser&&smtpPass
);

let transporter=null;

if(isEmailConfigured){
 transporter=nodemailer.createTransport({
  host:smtpHost,
  port:smtpPort,
  secure:smtpSecure,
  auth:{
   user:smtpUser,
   pass:smtpPass
  }
 });
}

export async function sendReminderEmail({to,subject,message}){
 if(!isEmailConfigured){
  console.warn("Reminder email skipped: SMTP is not configured.");
  return {skipped:true,reason:"smtp_not_configured"};
 }

 if(!to){
  console.warn("Reminder email skipped: recipient is missing.");
  return {skipped:true,reason:"missing_recipient"};
 }

 await transporter.sendMail({
  from:smtpFrom,
  to,
  subject,
  text:message
 });

 return {sent:true};
}

// backend/services/reminderSmsService.js
import twilio from "twilio";

const accountSid=process.env.TWILIO_ACCOUNT_SID||"";
const authToken=process.env.TWILIO_AUTH_TOKEN||"";
const fromNumber=process.env.TWILIO_PHONE_NUMBER||"";

const client=accountSid&&authToken?twilio(accountSid,authToken):null;

export async function sendReminderSms({to,message}){
 if(!client||!to||!fromNumber) return;
 await client.messages.create({
  body:message,
  from:fromNumber,
  to
 });
}

// backend/utils/generateToken.js
import jwt from "jsonwebtoken";

const generateToken=(id)=>{
 return jwt.sign({id},process.env.JWT_SECRET,{expiresIn:"30d"});
};

export default generateToken;

// backend/utils/getAppModules.js
import fs from "fs";
import path from "path";

const EXCLUDED_FILES=["index.js"];
const EXCLUDED_MODULES=[
 "user",
 "role",
 "permission",
 "business",
 "business_type",
 "businesstype",
 "user_role_assignment",
 "user_permission_override",
 "role_permission"
];

const APPS_ROOT=path.resolve(process.cwd(),"..");

const toModuleLabel=name=>{
 return name
  .replace(/Model$/i,"")
  .replace(/([a-z])([A-Z])/g,"$1 $2")
  .replace(/\b\w/g,char=>char.toUpperCase());
};

const toModuleValue=name=>{
 return name
  .replace(/Model$/i,"")
  .replace(/([a-z])([A-Z])/g,"$1_$2")
  .replace(/[\s\-]+/g,"_")
  .toLowerCase();
};

export const getAppModules=appKey=>{
 const modelsDir=path.join(APPS_ROOT,appKey,"backend","models");

 if(!fs.existsSync(modelsDir))
  throw new Error(`Models directory not found for appKey: ${appKey}`);

 const modules=[];

 const walk=dir=>{
  const entries=fs.readdirSync(dir,{withFileTypes:true});

  for(const entry of entries){
   const fullPath=path.join(dir,entry.name);

   if(entry.isDirectory()){
    walk(fullPath);
    continue;
   }

   if(!entry.name.endsWith(".js"))continue;
   if(EXCLUDED_FILES.includes(entry.name))continue;

   const baseName=entry.name.replace(/\.js$/,"");
   const value=toModuleValue(baseName);

   if(EXCLUDED_MODULES.includes(value))continue;

   modules.push({
    value,
    label:toModuleLabel(baseName)
   });
  }
 };

 walk(modelsDir);

 return [...new Map(modules.map(module=>[module.value,module])).values()]
  .sort((a,b)=>a.label.localeCompare(b.label));
};

