        </Form.Group>
       </Col>

       <Col md={4}>
        <Form.Group>
         <Form.Label>Next Run At</Form.Label>
         <Form.Control type="datetime-local" name="nextRunAt" value={formData.nextRunAt} onChange={handleChange}/>
        </Form.Group>
       </Col>

       <Col md={6}>
        <Form.Group>
         <Form.Label>Last Sent At</Form.Label>
         <Form.Control type="datetime-local" name="lastSentAt" value={formData.lastSentAt} onChange={handleChange}/>
        </Form.Group>
       </Col>

       <Col md={6}>
        <Form.Group>
         <Form.Label>Sent At</Form.Label>
         <Form.Control type="datetime-local" name="sentAt" value={formData.sentAt} onChange={handleChange}/>
        </Form.Group>
       </Col>

       <Col md={12} className="d-flex justify-content-end gap-2">
        <Button type="button" variant="secondary" onClick={onCancel} disabled={loading}>
         <XCircle size={16} className="me-1"/> Cancel
        </Button>
        <Button type="submit" variant="primary" disabled={loading}>
         <Save size={16} className="me-1"/> {isEditMode?"Update Reminder":"Create Reminder"}
        </Button>
       </Col>
      </Row>
     </Form>
    </Card.Body>
   </Card>

   <Modal show={showConfirm} onHide={()=>setShowConfirm(false)} centered>
    <Modal.Header closeButton>
     <Modal.Title>{isEditMode?"Update Reminder":"Confirm Reminder"}</Modal.Title>
    </Modal.Header>
    <Modal.Body>
     {isEditMode
      ?`Update this ${formData.isRecurring?`${formData.recurrenceRule||"recurring"} `:""}reminder for ${menteeName}?`
      :`Create ${formData.isRecurring?`${formData.recurrenceRule||"recurring"} `:""}reminder for ${menteeName}?`
     }
    </Modal.Body>
    <Modal.Footer>
     <Button variant="secondary" onClick={()=>setShowConfirm(false)} disabled={loading}>
      <XCircle size={16} className="me-1"/> Cancel
     </Button>
     <Button variant="primary" onClick={handleConfirmedSubmit} disabled={loading}>
      <Save size={16} className="me-1"/> {isEditMode?"Update":"Confirm"}
     </Button>
    </Modal.Footer>
   </Modal>
  </>
 );
}

import {useState,useEffect} from "react";
import {Form,Button,Row,Col} from "react-bootstrap";

export default function TagForm({tag,onSuccess})
{
 const[form,setForm]=useState({
  name:"",
  slug:"",
  description:"",
  color:"#0f766e"
 });

 const[saving,setSaving]=useState(false);

 useEffect(()=>{
  if(tag)
  {
   setForm({
    name:tag.name||"",
    slug:tag.slug||"",
    description:tag.description||"",
    color:tag.color||"#0f766e"
   });
  }
 },[tag]);

 const handleChange=(e)=>{
  const{name,value}=e.target;
  setForm(prev=>({...prev,[name]:value}));
 };

 const handleSubmit=async(e)=>{
  e.preventDefault();
  setSaving(true);

  try{

   const method=tag?"PUT":"POST";
   const url=tag?`/api/tags/${tag._id}`:"/api/tags";

   const res=await fetch(url,{
    method,
    headers:{
     "Content-Type":"application/json"
    },
    body:JSON.stringify(form)
   });

   const data=await res.json();

   if(data.success&&onSuccess)
    onSuccess(data.data);

  }
  catch(err){
   console.error("Tag save error",err);
  }
  finally{
   setSaving(false);
  }
 };

 return(

  <Form onSubmit={handleSubmit}>

   <Row className="mb-3">

    <Col md={6}>

     <Form.Group>

      <Form.Label>Name</Form.Label>

      <Form.Control
       type="text"
       name="name"
       value={form.name}
       onChange={handleChange}
       required
      />

     </Form.Group>

    </Col>

    <Col md={6}>

     <Form.Group>

      <Form.Label>Slug</Form.Label>

      <Form.Control
       type="text"
       name="slug"
       value={form.slug}
       onChange={handleChange}
      />

     </Form.Group>

    </Col>

   </Row>

   <Form.Group className="mb-3">

    <Form.Label>Description</Form.Label>

    <Form.Control
     as="textarea"
     rows={3}
     name="description"
     value={form.description}
     onChange={handleChange}
    />

   </Form.Group>

   <Row className="mb-3">

    <Col md={4}>

     <Form.Group>

      <Form.Label>Color</Form.Label>

      <Form.Control
       type="color"
       name="color"
       value={form.color}
       onChange={handleChange}
      />

     </Form.Group>

    </Col>

   </Row>

   <Button type="submit" disabled={saving}>
    {saving?"Saving...":tag?"Update Tag":"Create Tag"}
   </Button>

  </Form>

 );
}

// src/pages/forms/admin/AppKeyForm.jsx
import {useEffect,useState} from "react";
import {Button,Form,Modal,Row,Col,Spinner,Alert} from "react-bootstrap";

const emptyForm={businessRef:"",name:"",appKey:"",isActive:true};

const getObjectId=value=>{
 if(!value)return "";
 if(typeof value==="string")return value;
 if(typeof value==="object"){
  if(typeof value._id==="string")return value._id;
  if(value._id?.$oid)return value._id.$oid;
  if(typeof value.id==="string")return value.id;
  if(value.id?.$oid)return value.id.$oid;
 }
 return "";
};

export default function AppKeyForm({show,onHide,onSaved,initialData=null,businesses=[]}){
 const [formData,setFormData]=useState(emptyForm);
 const [saving,setSaving]=useState(false);
 const [message,setMessage]=useState({type:"",text:""});

 useEffect(()=>{
  if(initialData){
   setFormData({
    businessRef:getObjectId(initialData.businessRef),
    name:initialData.name||"",
    appKey:initialData.appKey||"",
    isActive:initialData.isActive!==false
   });
   setMessage({type:"",text:""});
   return;
  }

  setFormData(emptyForm);
  setMessage({type:"",text:""});
 },[initialData,show]);

 const api=async(url,options={})=>{
  const res=await fetch(url,{
   headers:{...(options.body?{"Content-Type":"application/json"}:{}),...(options.headers||{})},
   ...options
  });

  const data=await res.json().catch(()=>null);

  if(!res.ok)throw new Error(data?.message||data?.error||`Request failed (${res.status})`);

  return data;
 };

 const buildAppKey=value=>{
  return String(value||"")
   .trim()
   .toLowerCase()
   .replace(/[^a-z0-9\s-]/g,"")
   .replace(/\s+/g,"-")
   .replace(/-+/g,"-");
 };

 const handleChange=e=>{
  const {name,value,type,checked}=e.target;
  setFormData(prev=>({...prev,[name]:type==="checkbox"?checked:value}));
 };

 const handleNameBlur=()=>{
  if(initialData?._id||formData.appKey.trim())return;
  setFormData(prev=>({...prev,appKey:buildAppKey(prev.name)}));
 };

 const handleSubmit=async e=>{
  e.preventDefault();

  if(!formData.businessRef.trim()||!formData.name.trim()||!formData.appKey.trim()){
   setMessage({type:"danger",text:"Business, name and app key are required"});
   return;
  }

  try{
   setSaving(true);
   setMessage({type:"",text:""});

   const payload={
    businessRef:getObjectId(formData.businessRef),
    name:formData.name.trim(),
    appKey:buildAppKey(formData.appKey),
    isActive:!!formData.isActive
   };

   if(initialData?._id)await api(`/api/app-keys/${getObjectId(initialData._id)}`,{method:"PUT",body:JSON.stringify(payload)});
   else await api("/api/app-keys",{method:"POST",body:JSON.stringify(payload)});

   if(onSaved)await onSaved();
   onHide();
  }catch(err){
   setMessage({type:"danger",text:err.message||"Failed to save app key"});
  }finally{
   setSaving(false);
  }
 };

 return(
  <Modal show={show} onHide={onHide} centered backdrop="static" size="lg">
   <Modal.Header closeButton>
    <Modal.Title>{initialData?._id?"Edit App Key":"Add App Key"}</Modal.Title>
   </Modal.Header>

   <Form onSubmit={handleSubmit}>
    <Modal.Body>
     {message.text?(
      <Alert variant={message.type||"info"} className="mb-3">{message.text}</Alert>
     ):null}

     <Row className="g-3">
      <Col md={6}>
       <Form.Group>
        <Form.Label>Business</Form.Label>
        <Form.Select name="businessRef" value={formData.businessRef} onChange={handleChange} required>
         <option value="">Select business</option>
         {businesses.map(business=>{
          const id=getObjectId(business);
          return(
           <option key={id} value={id}>
            {business?.legalName||business?.name||id}
           </option>
          );
         })}
        </Form.Select>
       </Form.Group>
      </Col>

      <Col md={6}>
       <Form.Group>
        <Form.Label>Name</Form.Label>
        <Form.Control name="name" value={formData.name} onChange={handleChange} onBlur={handleNameBlur} required />
       </Form.Group>
      </Col>

      <Col md={6}>
       <Form.Group>
        <Form.Label>App Key</Form.Label>
        <Form.Control name="appKey" value={formData.appKey} onChange={handleChange} placeholder="ex: home-tracker" required />
        <Form.Text muted>Use the app folder name, like home-tracker or bible-study.</Form.Text>
       </Form.Group>
      </Col>

      <Col xs={12}>
       <Form.Check type="switch" id="appKeyIsActive" name="isActive" label="Active" checked={formData.isActive} onChange={handleChange}/>
      </Col>
     </Row>
    </Modal.Body>

    <Modal.Footer>
     <Button type="button" variant="outline-secondary" onClick={onHide} disabled={saving}>Cancel</Button>
     <Button type="submit" disabled={saving}>
      {saving?<Spinner size="sm" animation="border"/>:null}
      <span className={saving?"ms-2":""}>{initialData?._id?"Update":"Create"}</span>
     </Button>
    </Modal.Footer>
   </Form>
  </Modal>
 );
}

