export default function ReceiptFooterForm({
 show=false,
 onHide,
 onSaved,
 initialData={},
 loading=false,
 seasons=[],
 occasions=[]
}){
 const [formData,setFormData]=useState(defaultFormData);
 const [saving,setSaving]=useState(false);
 const [error,setError]=useState("");

 const seasonOptions=normalizeOptions(seasons);
 const occasionOptions=normalizeOptions(occasions);

 useEffect(()=>{
  setFormData({
   ...defaultFormData,
   ...initialData,
   seasonRef:getObjectId(initialData?.seasonRef),
   occasionRef:getObjectId(initialData?.occasionRef)
  });
 },[initialData,show]);

 const handleChange=e=>{
  const {name,type,value,checked}=e.target;
  setFormData(prev=>({...prev,[name]:type==="checkbox"?checked:value}));
 };

 const handleSubmit=async e=>{
  e.preventDefault();
  try{
   setSaving(true);
   setError("");
   const isEdit=Boolean(initialData?._id||initialData?.id);
   const id=initialData?._id||initialData?.id;
   const res=await fetch(isEdit?`/api/receipt-footers/${id}`:"/api/receipt-footers",{
    method:isEdit?"PUT":"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify({
     ...formData,
     seasonRef:getObjectId(formData.seasonRef)||null,
     occasionRef:getObjectId(formData.occasionRef)||null
    })
   });
   if(!res.ok){
    const errData=await res.json().catch(()=>null);
    throw new Error(errData?.message||`Failed to ${isEdit?"update":"save"} receipt footer.`);
   }
   const saved=await res.json().catch(()=>null);
   onSaved&&onSaved(saved);
  }catch(err){
   setError(err.message||"Unable to save receipt footer.");
  }finally{
   setSaving(false);
  }
 };

