              </Form.Group>
             </Col>

             <Col xs={12}>
              <Form.Group>
               <Form.Label>Description</Form.Label>
               <Form.Control as="textarea" rows={4} name="description" value={departmentForm.description} onChange={handleDepartmentChange}/>
              </Form.Group>
