// src/pages/admin/BusinessTypes.jsx
import {useEffect,useState} from "react";
import {Alert,Badge,Button,ButtonGroup,Card,Col,Form,Modal,Row,Spinner,Table} from "react-bootstrap";
import {Edit,Plus,RefreshCw,Trash2} from "lucide-react";

const emptyForm={name:"",code:"",description:"",isActive:true,notes:""};

export default function BusinessTypes(){
 const [businessTypes,setBusinessTypes]=useState([]);
 const [loading,setLoading]=useState(false);
 const [saving,setSaving]=useState(false);
 const [showModal,setShowModal]=useState(false);
 const [editingId,setEditingId]=useState("");
 const [formData,setFormData]=useState(emptyForm);
 const [message,setMessage]=useState({type:"",text:""});

 useEffect(()=>{
  fetchBusinessTypes();
 },[]);

 const api=async(url,options={})=>{
  const res=await fetch(url,{
   headers:{...(options.body?{"Content-Type":"application/json"}:{}),...(options.headers||{})},
   ...options
  });

  const data=await res.json().catch(()=>null);

  if(!res.ok)
   throw new Error(data?.message||data?.error||`Request failed (${res.status})`);

  return data;
 };

 const buildCode=value=>{
  return String(value||"")
   .trim()
   .toUpperCase()
   .replace(/[^A-Z0-9\s-]/g,"")
   .replace(/\s+/g,"-")
   .replace(/-+/g,"-");
 };

 const fetchBusinessTypes=async()=>{
  try{
   setLoading(true);
   setMessage({type:"",text:""});
   const res=await api("/api/business-types");
   setBusinessTypes(Array.isArray(res)?res:Array.isArray(res?.data)?res.data:[]);
  }catch(err){
   setMessage({type:"danger",text:err.message||"Failed to load business types"});
  }finally{
   setLoading(false);
  }
 };

 const openAddModal=()=>{
  setEditingId("");
  setFormData(emptyForm);
  setShowModal(true);
 };

 const openEditModal=item=>{
  setEditingId(String(item._id));
  setFormData({
   name:item.name||"",
   code:item.code||"",
   description:item.description||"",
   isActive:item.isActive!==false,
   notes:item.notes||""
  });
  setShowModal(true);
 };

 const closeModal=()=>{
  if(saving)return;
  setShowModal(false);
  setEditingId("");
  setFormData(emptyForm);
 };

 const handleChange=e=>{
  const {name,value,type,checked}=e.target;
  setFormData(prev=>({...prev,[name]:type==="checkbox"?checked:value}));
 };

 const handleNameBlur=()=>{
  if(editingId||formData.code.trim())return;
  setFormData(prev=>({...prev,code:buildCode(prev.name)}));
 };

 const handleSubmit=async e=>{
  e.preventDefault();

  if(!formData.name.trim())
  {
   setMessage({type:"danger",text:"Name is required"});
   return;
  }

  try{
   setSaving(true);
   setMessage({type:"",text:""});

   const payload={
    name:formData.name.trim(),
    code:buildCode(formData.code),
    description:formData.description.trim(),
    isActive:!!formData.isActive,
    notes:formData.notes.trim()
   };

   if(editingId)
    await api(`/api/business-types/${editingId}`,{method:"PUT",body:JSON.stringify(payload)});
   else
    await api("/api/business-types",{method:"POST",body:JSON.stringify(payload)});

   await fetchBusinessTypes();
   setMessage({type:"success",text:editingId?"Business type updated":"Business type created"});
   closeModal();
  }catch(err){
   setMessage({type:"danger",text:err.message||"Failed to save business type"});
  }finally{
   setSaving(false);
  }
 };

 const handleDelete=async id=>{
  if(!window.confirm("Delete this business type?"))return;

  try{
   setMessage({type:"",text:""});
   await api(`/api/business-types/${id}`,{method:"DELETE"});
   await fetchBusinessTypes();
   setMessage({type:"success",text:"Business type deleted"});
  }catch(err){
   setMessage({type:"danger",text:err.message||"Failed to delete business type"});
  }
 };

 return(
  <div className="py-4">
   <Row className="g-4">
    <Col xs={12}>
     <Card className="shadow-sm border-0">
      <Card.Body>
       <Row className="g-3 align-items-center">
        <Col md={8}>
         <h3 className="mb-1">Business Types</h3>
         <div className="text-muted">Manage business types like catering, food truck, restaurant, and more.</div>
        </Col>

        <Col md={4} className="d-flex justify-content-md-end gap-2">
         <Button variant="outline-secondary" onClick={fetchBusinessTypes} disabled={loading}>
          {loading?<Spinner size="sm" animation="border"/>:<RefreshCw size={16}/>}
         </Button>

         <Button onClick={openAddModal}>
          <Plus size={16}/>
          <span className="ms-2">Add Business Type</span>
         </Button>
        </Col>
       </Row>
      </Card.Body>
     </Card>
    </Col>

    {message.text?(
     <Col xs={12}>
      <Alert variant={message.type||"info"} className="mb-0">{message.text}</Alert>
     </Col>
    ):null}

    <Col xs={12}>
     <Card className="shadow-sm">
      <Card.Header>Business Types</Card.Header>

      <Card.Body className="p-0">
       <Table responsive hover className="mb-0 align-middle">
        <thead>
         <tr>
          <th>Name</th>
          <th>Code</th>
          <th>Description</th>
          <th>Status</th>
          <th className="text-end">Actions</th>
         </tr>
        </thead>

        <tbody>
         {!loading&&businessTypes.length===0?(
          <tr>
           <td colSpan="5" className="text-center py-4 text-muted">No business types found.</td>
          </tr>
         ):null}

         {businessTypes.map(item=>(
          <tr key={item._id}>
           <td>{item.name}</td>
           <td>{item.code||"-"}</td>
           <td>{item.description||"-"}</td>
           <td>
            <Badge bg={item.isActive?"success":"secondary"}>{item.isActive?"Active":"Inactive"}</Badge>
           </td>
           <td className="text-end">
            <ButtonGroup size="sm">
             <Button variant="outline-primary" onClick={()=>openEditModal(item)}>
              <Edit size={14}/>
             </Button>
             <Button variant="outline-danger" onClick={()=>handleDelete(item._id)}>
              <Trash2 size={14}/>
             </Button>
            </ButtonGroup>
           </td>
          </tr>
         ))}
        </tbody>
       </Table>
      </Card.Body>
     </Card>
    </Col>
   </Row>

   <Modal show={showModal} onHide={closeModal} centered backdrop="static" size="lg">
    <Form onSubmit={handleSubmit}>
     <Modal.Header closeButton={!saving}>
      <Modal.Title>{editingId?"Edit Business Type":"Add Business Type"}</Modal.Title>
     </Modal.Header>

     <Modal.Body>
      <Row className="g-3">
       <Col md={6}>
        <Form.Group>
         <Form.Label>Name</Form.Label>
         <Form.Control name="name" value={formData.name} onChange={handleChange} onBlur={handleNameBlur} required />
        </Form.Group>
       </Col>

       <Col md={6}>
        <Form.Group>
         <Form.Label>Code</Form.Label>
         <Form.Control name="code" value={formData.code} onChange={handleChange} placeholder="ex: CATERING" />
        </Form.Group>
       </Col>

       <Col xs={12}>
        <Form.Group>
         <Form.Label>Description</Form.Label>
         <Form.Control as="textarea" rows={3} name="description" value={formData.description} onChange={handleChange}/>
        </Form.Group>
       </Col>

       <Col xs={12}>
        <Form.Group>
         <Form.Label>Notes</Form.Label>
         <Form.Control as="textarea" rows={3} name="notes" value={formData.notes} onChange={handleChange}/>
        </Form.Group>
       </Col>

       <Col xs={12}>
        <Form.Check type="switch" id="businessTypeIsActive" name="isActive" label="Active" checked={formData.isActive} onChange={handleChange}/>
       </Col>
      </Row>
     </Modal.Body>

     <Modal.Footer>
      <Button type="button" variant="outline-secondary" onClick={closeModal} disabled={saving}>Cancel</Button>
      <Button type="submit" disabled={saving}>
       {saving?<Spinner size="sm" animation="border"/>:null}
       <span className={saving?"ms-2":""}>{editingId?"Update":"Create"}</span>
      </Button>
     </Modal.Footer>
    </Form>
   </Modal>
  </div>
 );
}

//src/pages/admin/Footers.jsx
import {useEffect,useMemo,useRef,useState} from "react";
import {Modal,Button,Alert,Table,Accordion} from "react-bootstrap";
import FooterForm from "../forms/admin/FooterForm.jsx";
import {sortItems} from "../../utils/sortItems.js";
import "../../styles/Footers.css";

const defaultFormData={
 business_id:"",
 seasonRef:"",
 name:"",
 lines:[""],
 showDate:true,
 showTime:true,
 showCashier:false,
 isDefault:false,
 isActive:true,
 notes:""
};

const getRows=data=>{
 if(Array.isArray(data))return data;
 if(Array.isArray(data?.data))return data.data;
 if(Array.isArray(data?.footers))return data.footers;
 if(Array.isArray(data?.businesses))return data.businesses;
 if(Array.isArray(data?.seasons))return data.seasons;
 return [];
};

const getId=value=>{
 if(!value)return "";
 if(typeof value==="string")return value;
 if(typeof value==="object")return String(value?._id||value?.id||"");
 return "";
};

const formatValue=value=>{
 if(value===null||value===undefined||value==="")return "-";
 if(typeof value==="object")return value?.name||value?.legalName||value?.code||value?._id||"-";
 return String(value);
};

export default function Footers(){
 const [footers,setFooters]=useState([]);
 const [businesses,setBusinesses]=useState([]);
 const [seasons,setSeasons]=useState([]);
 const [loading,setLoading]=useState(true);
 const [saving,setSaving]=useState(false);
 const [deleting,setDeleting]=useState(false);
 const [error,setError]=useState("");
 const [successMessage,setSuccessMessage]=useState("");
 const [showFormModal,setShowFormModal]=useState(false);
 const [showDeleteModal,setShowDeleteModal]=useState(false);
 const [modalMode,setModalMode]=useState("add");
 const [formInitialData,setFormInitialData]=useState(defaultFormData);
 const [activeFooter,setActiveFooter]=useState(null);
 const successTimerRef=useRef(null);

 const clearSuccessTimer=()=>{
  if(successTimerRef.current){
   clearTimeout(successTimerRef.current);
   successTimerRef.current=null;
  }
 };

 const showTimedSuccess=msg=>{
  clearSuccessTimer();
  setSuccessMessage(msg);
  successTimerRef.current=setTimeout(()=>{
   setSuccessMessage("");
   successTimerRef.current=null;
  },2500);
 };

 const loadBusinesses=async()=>{
  const res=await fetch("/api/businesses");
  const data=await res.json();
  setBusinesses(getRows(data));
 };

 const loadSeasons=async()=>{
  const res=await fetch("/api/seasons");
  const data=await res.json();
  setSeasons(getRows(data));
 };

 const loadFooters=async()=>{
  const res=await fetch("/api/footers");
  const data=await res.json();
  setFooters(getRows(data));
 };

 useEffect(()=>{
  (async()=>{
   try{
    setLoading(true);
    setError("");
    await Promise.all([loadBusinesses(),loadSeasons(),loadFooters()]);
   }catch(err){
    setError("Load failed");
   }finally{
    setLoading(false);
   }
  })();
  return()=>clearSuccessTimer();
 },[]);

 const footersByBusiness=useMemo(()=>{
  const grouped={};
  footers.forEach(f=>{
   const businessId=getId(f.business_id)||"unassigned";
   if(!grouped[businessId])grouped[businessId]=[];
   grouped[businessId].push(f);
  });
  return grouped;
 },[footers]);

 const sortedBusinesses=useMemo(()=>sortItems(businesses,business=>business.legalName||business.name||business.code||""),[businesses]);

 const openAdd=businessId=>{
  setModalMode("add");
  setActiveFooter(null);
  setFormInitialData({
   ...defaultFormData,
   business_id:businessId||""
  });
  setShowFormModal(true);
 };

 const openEdit=footer=>{
  if(!footer)return;
  setModalMode("edit");
  setActiveFooter(footer);
  setFormInitialData({
   ...defaultFormData,
   ...footer,
   business_id:getId(footer.business_id),
   seasonRef:getId(footer.seasonRef)
  });
  setShowFormModal(true);
 };

 const openDelete=footer=>{
  if(!footer)return;
  setActiveFooter(footer);
  setShowDeleteModal(true);
 };

 const save=async(payload)=>{
  try{
   setSaving(true);
   setError("");
   const isEdit=modalMode==="edit"&&activeFooter?._id;
   const url=isEdit?`/api/footers/${activeFooter._id}`:"/api/footers";
   const method=isEdit?"PUT":"POST";
   const res=await fetch(url,{
    method,
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify(payload)
   });
   if(!res.ok)throw new Error("Save failed");
   await loadFooters();
   setShowFormModal(false);
   setActiveFooter(null);
   showTimedSuccess(isEdit?"Updated":"Created");
  }catch(err){
   setError("Save failed");
  }finally{
   setSaving(false);
  }
 };

 const remove=async()=>{
  if(!activeFooter?._id)return;
  try{
   setDeleting(true);
   setError("");
   const res=await fetch(`/api/footers/${activeFooter._id}`,{method:"DELETE"});
   if(!res.ok)throw new Error("Delete failed");
   await loadFooters();
   setShowDeleteModal(false);
   setActiveFooter(null);
   showTimedSuccess("Deleted");
  }catch(err){
   setError("Delete failed");
  }finally{
   setDeleting(false);
  }
 };

 return(
  <div className="footers-page">
   <div className="footers-wrap">

    <div className="footers-topbar">
     <h1>Footers</h1>
    </div>

    {error&&<Alert variant="danger">{error}</Alert>}
    {successMessage&&<Alert variant="success">{successMessage}</Alert>}

    {loading?(
     <div className="footers-loading">Loading...</div>
    ):(
     <Accordion alwaysOpen className="footers-accordion">
      {sortedBusinesses.map((business,index)=>{
       const businessId=getId(business);
       const businessFooters=sortItems(footersByBusiness[businessId]||[],footer=>footer.name||footer.notes||"");

       return(
        <Accordion.Item eventKey={String(index)} key={businessId} className="footers-accordion-item">
         <Accordion.Header>
          <div className="footers-business-heading">
           <div className="footers-business-title">{business.legalName||business.name||"Business"}</div>
           <div className="footers-business-code">{formatValue(business.code)}</div>
          </div>
         </Accordion.Header>

         <Accordion.Body>
          <div className="footers-business-toolbar">
           <Button className="footers-action-btn" onClick={()=>openAdd(businessId)}>Add Footer</Button>
          </div>

          <div className="footers-table-wrap">
           <Table responsive className="footers-table">
            <thead>
             <tr>
              <th>Name</th>
              <th>Season</th>
              <th>Lines</th>
              <th>Show Date</th>
              <th>Show Time</th>
              <th>Show Cashier</th>
              <th>Default</th>
              <th>Active</th>
              <th>Notes</th>
              <th>Actions</th>
             </tr>
            </thead>
            <tbody>
             {businessFooters.length>0?businessFooters.map(footer=>(
              <tr key={footer._id}>
               <td>{footer.name||"-"}</td>
               <td>{formatValue(footer.seasonRef)}</td>
               <td>{Array.isArray(footer.lines)&&footer.lines.length>0?footer.lines.filter(Boolean).join(" | "):"-"}</td>
               <td>{footer.showDate?"Yes":"No"}</td>
               <td>{footer.showTime?"Yes":"No"}</td>
               <td>{footer.showCashier?"Yes":"No"}</td>
               <td>{footer.isDefault?"Yes":"No"}</td>
               <td>{footer.isActive?"Yes":"No"}</td>
               <td>{footer.notes||"-"}</td>
               <td>
                <div className="footers-actions">
                 <Button size="sm" className="footers-action-btn" onClick={()=>openEdit(footer)}>Edit</Button>
                 <Button size="sm" variant="danger" className="footers-delete-btn" onClick={()=>openDelete(footer)}>Delete</Button>
                </div>
               </td>
              </tr>
             )):(
              <tr>
               <td colSpan="10" className="footers-empty-cell">No footers for this business.</td>
              </tr>
             )}
            </tbody>
           </Table>
          </div>
         </Accordion.Body>
        </Accordion.Item>
       );
      })}
     </Accordion>
    )}

    {!loading&&businesses.length===0&&(
     <div className="footers-empty-state">No businesses found.</div>
    )}

    <Modal show={showFormModal} onHide={()=>setShowFormModal(false)} size="xl" centered>
     <Modal.Body>
      <FooterForm
       initialData={formInitialData}
       onSubmit={save}
       loading={saving}
       businesses={businesses}
       seasons={seasons}
      />
     </Modal.Body>
    </Modal>

    <Modal show={showDeleteModal} onHide={()=>setShowDeleteModal(false)} centered>
     <Modal.Body>Confirm delete?</Modal.Body>
     <Modal.Footer>
      <Button onClick={()=>setShowDeleteModal(false)}>Cancel</Button>
      <Button variant="danger" onClick={remove} disabled={deleting}>{deleting?"Deleting...":"Delete"}</Button>
     </Modal.Footer>
    </Modal>

   </div>
  </div>
 );
}

