//src/pages/admin/TaxRatesPage.jsx
import {useEffect,useMemo,useState} from "react";
import {Button,Card,Col,Form,InputGroup,Modal,Row,Table,Alert,Badge} from "react-bootstrap";
import TaxRateForm from "../forms/admin/TaxRateForm.jsx";

const getObjectId=value=>{
 if(!value)return "";
 if(typeof value==="string")return value;
 if(typeof value==="object")return String(value?._id||value?.id||value?.value||"");
 return "";
};

const getStateLabel=value=>{
 if(!value)return "";
 if(typeof value==="string")return value;
 return value?.name||value?.title||value?.code||"";
};

export default function TaxRatesPage(){
 const [rows,setRows]=useState([]);
 const [states,setStates]=useState([]);
 const [loading,setLoading]=useState(false);
 const [saving,setSaving]=useState(false);
 const [deletingId,setDeletingId]=useState("");
 const [query,setQuery]=useState("");
 const [stateFilter,setStateFilter]=useState("");
 const [activeFilter,setActiveFilter]=useState("all");
 const [showModal,setShowModal]=useState(false);
 const [editingItem,setEditingItem]=useState(null);
 const [status,setStatus]=useState({show:false,variant:"success",message:""});

 const filteredRows=useMemo(()=>{
  return rows.filter(item=>{
   const matchesQuery=!query.trim()||[
    item?.name,
    item?.code,
    getStateLabel(item?.stateRef),
    item?.notes
   ].some(value=>String(value||"").toLowerCase().includes(query.trim().toLowerCase()));
   const matchesState=!stateFilter||getObjectId(item?.stateRef)===stateFilter;
   const matchesActive=activeFilter==="all"||String(!!item?.isActive)===activeFilter;
   return matchesQuery&&matchesState&&matchesActive;
  });
 },[rows,query,stateFilter,activeFilter]);

 useEffect(()=>{
  if(!status.show)return;
  const timer=setTimeout(()=>{
   setStatus(prev=>({...prev,show:false}));
  },10000);
  return()=>clearTimeout(timer);
 },[status]);

 const showTimedStatus=(variant,message)=>{
  setStatus({show:true,variant,message});
 };

 const loadStates=async()=>{
  try{
   const res=await fetch("/api/states",{headers:{"Content-Type":"application/json"}});
   if(!res.ok)throw new Error("Failed to fetch states.");
   const data=await res.json().catch(()=>[]);
   const nextRows=Array.isArray(data)?data:Array.isArray(data?.data)?data.data:Array.isArray(data?.states)?data.states:[];
   setStates(nextRows);
  }catch(error){
   showTimedStatus("danger",error?.message||"Unable to load states.");
  }
 };

 const loadRows=async()=>{
  setLoading(true);
  try{
   const res=await fetch("/api/tax-rates",{headers:{"Content-Type":"application/json"}});
   if(!res.ok)throw new Error("Failed to fetch tax rates.");
   const data=await res.json().catch(()=>[]);
   const nextRows=Array.isArray(data)?data:Array.isArray(data?.data)?data.data:Array.isArray(data?.taxRates)?data.taxRates:[];
   setRows(nextRows);
  }catch(error){
   showTimedStatus("danger",error?.message||"Unable to load tax rates.");
  }finally{
   setLoading(false);
  }
 };

 useEffect(()=>{
  loadStates();
  loadRows();
 },[]);

 const handleAdd=()=>{
  setEditingItem(null);
  setShowModal(true);
 };

 const handleEdit=item=>{
  setEditingItem(item);
  setShowModal(true);
 };

 const handleSave=async payload=>{
  setSaving(true);
  try{
   const isEdit=!!getObjectId(editingItem?._id||payload?._id);
   const targetId=getObjectId(editingItem?._id||payload?._id);
   const res=await fetch(isEdit?`/api/tax-rates/${targetId}`:"/api/tax-rates",{
    method:isEdit?"PUT":"POST",
    headers:{"Content-Type":"application/json"},
    body:JSON.stringify(payload)
   });
   const data=await res.json().catch(()=>null);
   if(!res.ok)throw new Error(data?.message||`Failed to ${isEdit?"update":"create"} tax rate.`);
   await loadRows();
   setShowModal(false);
   setEditingItem(null);
   showTimedStatus("success",`Tax rate ${isEdit?"updated":"created"} successfully.`);
   return data;
  }catch(error){
   showTimedStatus("danger",error?.message||"Unable to save tax rate.");
   throw error;
  }finally{
   setSaving(false);
  }
 };

 const handleDelete=async item=>{
  const targetId=getObjectId(item?._id);
  if(!targetId)return;
  const confirmed=window.confirm(`Delete tax rate "${item?.name||""}"?`);
  if(!confirmed)return;
  setDeletingId(targetId);
  try{
   const res=await fetch(`/api/tax-rates/${targetId}`,{
    method:"DELETE",
    headers:{"Content-Type":"application/json"}
   });
   const data=await res.json().catch(()=>null);
   if(!res.ok)throw new Error(data?.message||"Failed to delete tax rate.");
   await loadRows();
   showTimedStatus("success","Tax rate deleted successfully.");
  }catch(error){
   showTimedStatus("danger",error?.message||"Unable to delete tax rate.");
  }finally{
   setDeletingId("");
  }
 };

 return(
  <>
   {status.show?(
    <Alert variant={status.variant} dismissible onClose={()=>setStatus(prev=>({...prev,show:false}))} className="mb-3">
     {status.message}
    </Alert>
   ):null}

   <Card className="border-0 shadow-sm">
    <Card.Body>
     <Row className="g-3 align-items-end mb-3">
      <Col md={4}>
       <Form.Label className="fw-semibold">Search</Form.Label>
       <Form.Control
        type="text"
        value={query}
        onChange={e=>setQuery(e.target.value)}
        placeholder="Search tax rates"
       />
      </Col>

      <Col md={3}>
       <Form.Label className="fw-semibold">State</Form.Label>
       <Form.Select value={stateFilter} onChange={e=>setStateFilter(e.target.value)}>
        <option value="">All States</option>
        {states.map(item=>(
         <option key={getObjectId(item)} value={getObjectId(item)}>
          {getStateLabel(item)}
         </option>
        ))}
       </Form.Select>
      </Col>

      <Col md={3}>
       <Form.Label className="fw-semibold">Status</Form.Label>
       <Form.Select value={activeFilter} onChange={e=>setActiveFilter(e.target.value)}>
        <option value="all">All</option>
        <option value="true">Active</option>
        <option value="false">Inactive</option>
       </Form.Select>
      </Col>

      <Col md={2}>
       <div className="d-grid">
        <Button type="button" onClick={handleAdd}>Add Tax Rate</Button>
       </div>
      </Col>
     </Row>

     <div className="table-responsive">
      <Table striped hover className="align-middle mb-0">
       <thead>
        <tr>
         <th>Name</th>
         <th>Code</th>
         <th>State</th>
         <th>Rate</th>
         <th>Default</th>
         <th>Status</th>
         <th className="text-end">Actions</th>
        </tr>
       </thead>
       <tbody>
        {!loading&&filteredRows.length===0?(
         <tr>
          <td colSpan={7} className="text-center py-4">No tax rates found.</td>
         </tr>
        ):null}

        {filteredRows.map(item=>(
         <tr key={getObjectId(item)}>
          <td>{item?.name||""}</td>
          <td>{item?.code||""}</td>
          <td>{getStateLabel(item?.stateRef)}</td>
          <td>{Number(item?.rate||0).toFixed(3)}%</td>
          <td>{item?.isDefault?<Badge bg="success">Default</Badge>:""}</td>
          <td>{item?.isActive?<Badge bg="primary">Active</Badge>:<Badge bg="secondary">Inactive</Badge>}</td>
          <td className="text-end">
           <div className="d-inline-flex gap-2">
            <Button type="button" size="sm" variant="outline-primary" onClick={()=>handleEdit(item)}>Edit</Button>
            <Button type="button" size="sm" variant="outline-danger" disabled={deletingId===getObjectId(item)} onClick={()=>handleDelete(item)}>
             {deletingId===getObjectId(item)?"Deleting...":"Delete"}
            </Button>
           </div>
          </td>
         </tr>
        ))}

        {loading?(
         <tr>
          <td colSpan={7} className="text-center py-4">Loading...</td>
         </tr>
        ):null}
       </tbody>
      </Table>
     </div>
    </Card.Body>
   </Card>

   <Modal show={showModal} onHide={()=>{setShowModal(false);setEditingItem(null);}} centered backdrop="static" size="lg">
    <Modal.Header closeButton>
     <Modal.Title>{editingItem?"Edit Tax Rate":"Add Tax Rate"}</Modal.Title>
    </Modal.Header>
    <Modal.Body>
     <TaxRateForm
      initialData={editingItem||{}}
      onSubmit={handleSave}
      onSaved={()=>{}}
      onHide={()=>{
       setShowModal(false);
       setEditingItem(null);
      }}
      loading={saving}
      states={states}
     />
    </Modal.Body>
   </Modal>
  </>
 );
}

import {requestJson} from "@shared/requestJson.js";
//src/pages/admin/Vendors.jsx
import {useEffect,useMemo,useRef,useState} from "react";
import {Modal,Button,Alert} from "react-bootstrap";
import VendorForm from "../forms/admin/VendorForm.jsx";
import "../../styles/Vendors.css";

const defaultFormData={business_id:"",legalName:"",code:"",dbaName:"",vendorCategory:"",email:"",phone:"",isPreferred:false,isActive:true};

const getRows=d=>Array.isArray(d)?d:Array.isArray(d?.data)?d.data:Array.isArray(d?.vendors)?d.vendors:Array.isArray(d?.businesses)?d.businesses:[];
const getId=v=>!v?"":typeof v==="string"?v:String(v?._id||v?.id||"");

export default function Vendors(){
 const [error,setError]=useState("");
 const [saving,setSaving]=useState(false);
 const [rows,setRows]=useState([]),[businesses,setBusinesses]=useState([]);
 const [selectedId,setSelectedId]=useState(""),[showForm,setShowForm]=useState(false),[showDelete,setShowDelete]=useState(false);
 const [mode,setMode]=useState("add"),[initial,setInitial]=useState(defaultFormData),[success,setSuccess]=useState(""); const t=useRef(null);

 const ok=m=>{if(t.current)clearTimeout(t.current);t.current=setTimeout(()=>setSuccess(""),2500);setSuccess(m)};

 const load=async(preferredId)=>{
  const [businessData,vendorData]=await Promise.all([requestJson("/api/businesses"),requestJson("/api/vendors")]);
  setBusinesses(getRows(businessData));
  const list=getRows(vendorData);
  setRows(list);
  setSelectedId(current=>{const desired=preferredId||current;return list.some(row=>String(row._id)===String(desired))?String(desired):String(list[0]?._id||"");});
 };

 useEffect(()=>{load().catch(err=>setError(err.message));return()=>t.current&&clearTimeout(t.current)},[]);

 const selected=useMemo(()=>rows.find(x=>String(x._id)===String(selectedId)),[rows,selectedId]);

 const openAdd=()=>{setMode("add");setInitial(defaultFormData);setShowForm(true)};
 const openEdit=()=>{if(!selected)return;setMode("edit");setInitial({...defaultFormData,...selected,business_id:getId(selected.business_id)});setShowForm(true)};
 const save=async(p)=>{
  if(saving)return;
  const isEdit=mode==="edit";setError("");setSuccess("");setSaving(true);
  try{
   const saved=await requestJson(isEdit?`/api/vendors/${selected._id}`:"/api/vendors",{method:isEdit?"PUT":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(p)});
   setShowForm(false);
   await load(saved?._id||saved?.data?._id);
   ok(isEdit?"Updated":"Created");
  }catch(err){setError(err.message);}finally{setSaving(false);}
 };
 const remove=async()=>{
  if(saving||!selected)return;setError("");setSuccess("");setSaving(true);
  try{await requestJson(`/api/vendors/${selected._id}`,{method:"DELETE"});setShowDelete(false);await load();ok("Deleted");}
  catch(err){setError(err.message);}finally{setSaving(false);}
 };

 return(
  <div className="vendors-page"><div className="vendors-wrap">

   <div className="vendors-topbar">
    <h1>Vendors</h1>
    <div className="d-flex gap-2">
     <Button onClick={openAdd}>Add</Button>
     <Button onClick={openEdit} disabled={!selected}>Edit</Button>
     <Button variant="danger" onClick={()=>setShowDelete(true)} disabled={!selected}>Delete</Button>
    </div>
   </div>

   {error&&<Alert variant="danger">{error}</Alert>}
   {success&&<Alert variant="success">{success}</Alert>}

   <div className="vendors-layout">

    <div className="vendors-col vendors-list">
     <div className="vendors-col-header">
      <h3>Vendor List</h3>
     </div>
     <div className="vendors-col-body">
      {rows.map(v=>(
       <button key={v._id} onClick={()=>setSelectedId(v._id)} className={`vendors-list-item ${selectedId===v._id?"active":""}`}>
        {v.legalName}
       </button>
      ))}
     </div>
    </div>

    <div className="vendors-col vendors-details">
