         </InlineField>
        </Col>

        <Col md={12}>
         <InlineField label="Template Key" labelMd={2} inputMd={10}>
          <Form.Control type="text" name="templateKey" value={formData.templateKey} onChange={handleChange} />
         </InlineField>
        </Col>

        <Col md={6}>
