         </InlineField>
        </Col>

        <Col md={6}>
         <InlineField label="Default" labelMd={4} inputMd={8}>
          <Form.Check type="switch" id="receiptTemplateIsDefault" name="isDefault" checked={formData.isDefault} onChange={handleChange} />
         </InlineField>
        </Col>

        <Col md={6}>
         <InlineField label="Active" labelMd={4} inputMd={8}>
          <Form.Check type="switch" id="receiptTemplateIsActive" name="isActive" checked={formData.isActive} onChange={handleChange} />
         </InlineField>
        </Col>

        <Col md={12}>
         <InlineField label="Notes" labelMd={2} inputMd={10}>
          <Form.Control as="textarea" rows={3} name="notes" value={formData.notes} onChange={handleChange} />
         </InlineField>
        </Col>
       </Row>
      </Card.Body>
     </Card>

     <div className="d-flex justify-content-end gap-2 mt-3">
      <Button type="button" variant="outline-secondary" onClick={onHide} disabled={saving||loading}>Cancel</Button>
      <Button type="submit" disabled={saving||loading}>{saving?"Saving...":"Save Receipt Template"}</Button>
     </div>
    </Form>
   </Modal.Body>
  </>
 );
}

