// src/pages/forms/WeeklySessionForm.jsx
import {useEffect,useMemo,useState} from "react";
import {Alert,Button,Col,Form,Row,Spinner} from "react-bootstrap";

const initialForm={
 weekNumber:"",
 sessionDate:"",
 sessionType:"",
 competencyDiscussed:"",
 actionPlanStep:"",
 howWhenCompleted:"",
 notes:"",
 status:"scheduled"
};

const normalizeCollection=(payload,preferredKey)=>{
 if(Array.isArray(payload))return payload;
 if(!payload||typeof payload!=="object")return [];
 if(preferredKey&&Array.isArray(payload[preferredKey]))return payload[preferredKey];
 if(Array.isArray(payload.data))return payload.data;
 if(Array.isArray(payload.items))return payload.items;
 if(Array.isArray(payload.results))return payload.results;
 if(Array.isArray(payload.rows))return payload.rows;
 for(const value of Object.values(payload)){
  if(Array.isArray(value))return value;
 }
 return [];
};

const getStoredUser=()=>{
 const keys=["userInfo","user","authUser","currentUser"];
 for(const key of keys){
  try{
   const raw=localStorage.getItem(key)||sessionStorage.getItem(key);
   if(!raw)continue;
   const parsed=JSON.parse(raw);
   if(parsed?._id||parsed?.id||parsed?.email)return parsed;
   if(parsed?.user?._id||parsed?.user?.id||parsed?.user?.email)return parsed.user;
   if(parsed?.data?._id||parsed?.data?.id||parsed?.data?.email)return parsed.data;
  }catch(err){
   console.error(`Failed to parse stored user from ${key}`,err);
  }
 }
 return null;
};

function WeeklySessionForm({mode="create",menteeId,session,onSuccess,onCancel,user}){
 const isEdit=mode==="edit"&&Boolean(session?._id);

 const [form,setForm]=useState(initialForm);
 const [meetingMethods,setMeetingMethods]=useState([]);
 const [loading,setLoading]=useState(true);
 const [saving,setSaving]=useState(false);
 const [error,setError]=useState("");
 const [storedUser,setStoredUser]=useState(()=>getStoredUser());

 useEffect(()=>{
  setStoredUser(getStoredUser());
 },[]);

 const currentUser=user?._id||user?.id?user:storedUser;
 const currentUserId=currentUser?._id||currentUser?.id||"";

 const formatDateTimeLocal=value=>{
  if(!value)return"";
  const date=new Date(value);
  if(Number.isNaN(date.getTime()))return"";
  const year=date.getFullYear();
  const month=String(date.getMonth()+1).padStart(2,"0");
  const day=String(date.getDate()).padStart(2,"0");
  const hours=String(date.getHours()).padStart(2,"0");
  const minutes=String(date.getMinutes()).padStart(2,"0");
  return`${year}-${month}-${day}T${hours}:${minutes}`;
 };

 useEffect(()=>{
  let mounted=true;

  const loadForm=async()=>{
   try{
    setLoading(true);
    setError("");

    const urls=["/api/meeting-methods","/api/meeting-methods/list"];
    let methods=[];

    for(const url of urls){
     try{
      const res=await fetch(url,{credentials:"include"});
      if(!res.ok)continue;
      const data=await res.json();
      methods=normalizeCollection(data,"meetingMethods");
      if(methods.length)break;
     }catch{
      methods=[];
     }
    }

    if(mounted)setMeetingMethods(Array.isArray(methods)?methods:[]);

    if(mounted){
      if(isEdit&&session){
       setForm({
        weekNumber:session.weekNumber??"",
        sessionDate:formatDateTimeLocal(session.sessionDate),
        sessionType:typeof session.sessionType==="string"?session.sessionType:session.sessionType?._id||"",
        competencyDiscussed:session.competencyDiscussed||"",
        actionPlanStep:session.actionPlanStep||"",
        howWhenCompleted:session.howWhenCompleted||"",
        notes:session.notes||"",
        status:session.status||"scheduled"
       });
      }else{
       setForm(initialForm);
      }
    }
   }catch(err){
    if(mounted)setError(err.message||"Failed to load form data");
   }finally{
    if(mounted)setLoading(false);
   }
  };

  loadForm();

  return()=>{
   mounted=false;
  };
 },[isEdit,session]);

 const payload=useMemo(()=>({
  mentee:menteeId,
  weekNumber:Number(form.weekNumber||0),
  sessionDate:form.sessionDate?new Date(form.sessionDate).toISOString():null,
  sessionType:form.sessionType||null,
  competencyDiscussed:form.competencyDiscussed.trim(),
  actionPlanStep:form.actionPlanStep.trim(),
  howWhenCompleted:form.howWhenCompleted.trim(),
  notes:form.notes.trim(),
  status:form.status,
  createdBy:currentUserId
 }),[form,menteeId,currentUserId]);

 const handleChange=e=>{
  const {name,value}=e.target;
  setForm(prev=>({...prev,[name]:value}));
 };

 const handleSubmit=async e=>{
  e.preventDefault();

  try{
   setSaving(true);
   setError("");

   if(!menteeId)throw new Error("Missing mentee id");
   if(!currentUserId)throw new Error("No logged in user found");

   const requests=isEdit?[
    {url:`/api/weekly-sessions/${session._id}`,method:"PUT"},
    {url:`/api/weekly-sessions/update/${session._id}`,method:"PUT"}
   ]:[
    {url:"/api/weekly-sessions",method:"POST"},
    {url:"/api/weekly-sessions/create",method:"POST"}
   ];

   let successData=null;
   let errorMessage=`Failed to ${isEdit?"update":"create"} session`;

   for(const request of requests){
    try{
     const res=await fetch(request.url,{
      method:request.method,
      credentials:"include",
      headers:{"Content-Type":"application/json"},
      body:JSON.stringify(payload)
     });

     let data=null;
     try{
      data=await res.json();
     }catch{
      data=null;
     }

     if(res.ok){
      successData=data;
      break;
     }

     errorMessage=data?.message||data?.error||errorMessage;
    }catch(err){
     errorMessage=err.message||errorMessage;
    }
   }

   if(!successData)throw new Error(errorMessage);

   if(onSuccess)onSuccess(successData);
  }catch(err){
   setError(err.message||"Failed to save session");
  }finally{
   setSaving(false);
  }
 };

 if(loading){
  return(
   <div className="py-4 text-center">
    <Spinner animation="border" />
   </div>
  );
 }

 return(
  <Form onSubmit={handleSubmit}>
   {error?<Alert variant="danger" className="mb-3">{error}</Alert>:null}

   <Row className="g-3">
    <Col md={6}>
     <Form.Group>
      <Form.Label>Week Number</Form.Label>
      <Form.Control type="number" min="1" name="weekNumber" value={form.weekNumber} onChange={handleChange} required />
     </Form.Group>
    </Col>

    <Col md={6}>
     <Form.Group>
      <Form.Label>Status</Form.Label>
      <Form.Select name="status" value={form.status} onChange={handleChange} required>
       <option value="scheduled">Scheduled</option>
       <option value="completed">Completed</option>
       <option value="missed">Missed</option>
       <option value="cancelled">Cancelled</option>
       <option value="rescheduled">Rescheduled</option>
      </Form.Select>
     </Form.Group>
    </Col>

    <Col md={6}>
     <Form.Group>
      <Form.Label>Session Date</Form.Label>
      <Form.Control type="datetime-local" name="sessionDate" value={form.sessionDate} onChange={handleChange} required />
     </Form.Group>
    </Col>

    <Col md={6}>
     <Form.Group>
      <Form.Label>Session Type</Form.Label>
      <Form.Select name="sessionType" value={form.sessionType} onChange={handleChange}>
       <option value="">Select meeting method</option>
       {meetingMethods.map(item=>(
        <option key={item._id} value={item._id}>{item.name||item.label||item.methodName}</option>
       ))}
      </Form.Select>
     </Form.Group>
    </Col>

    <Col md={12}>
     <Form.Group>
      <Form.Label>Competency Discussed</Form.Label>
      <Form.Control type="text" name="competencyDiscussed" value={form.competencyDiscussed} onChange={handleChange} />
     </Form.Group>
    </Col>

    <Col md={12}>
     <Form.Group>
      <Form.Label>Action Plan Step</Form.Label>
      <Form.Control as="textarea" rows={2} name="actionPlanStep" value={form.actionPlanStep} onChange={handleChange} />
     </Form.Group>
    </Col>

    <Col md={12}>
     <Form.Group>
      <Form.Label>How / When Completed</Form.Label>
      <Form.Control as="textarea" rows={2} name="howWhenCompleted" value={form.howWhenCompleted} onChange={handleChange} />
     </Form.Group>
    </Col>

    <Col md={12}>
     <Form.Group>
      <Form.Label>Notes</Form.Label>
      <Form.Control as="textarea" rows={4} name="notes" value={form.notes} onChange={handleChange} />
     </Form.Group>
    </Col>
   </Row>

   <div className="d-flex justify-content-end gap-2 mt-4">
    <Button type="button" variant="outline-secondary" onClick={onCancel} disabled={saving}>Cancel</Button>
    <Button type="submit" variant="dark" disabled={saving}>
     {saving?(isEdit?"Saving...":"Creating..."):(isEdit?"Update Session":"Create Session")}
    </Button>
   </div>
  </Form>
 );
}

export default WeeklySessionForm;

// src/pages/forms/admin/AppKeyForm.jsx
import {useEffect,useState} from "react";
import {Button,Form,Modal,Row,Col,Spinner,Alert} from "react-bootstrap";

const emptyForm={businessRef:"",name:"",appKey:"",isActive:true};

const getObjectId=value=>{
 if(!value)return "";
 if(typeof value==="string")return value;
 if(typeof value==="object")return String(value._id||value.id||"");
 return "";
};

export default function AppKeyForm({show,onHide,onSaved,initialData=null,businesses=[]}){
 const [formData,setFormData]=useState(emptyForm);
 const [saving,setSaving]=useState(false);
 const [message,setMessage]=useState({type:"",text:""});

 useEffect(()=>{
  if(initialData){
   setFormData({
    businessRef:getObjectId(initialData.businessRef),
    name:initialData.name||"",
    appKey:initialData.appKey||"",
    isActive:initialData.isActive!==false
   });
   setMessage({type:"",text:""});
   return;
  }

  setFormData(emptyForm);
  setMessage({type:"",text:""});
 },[initialData,show]);

 const api=async(url,options={})=>{
  const res=await fetch(url,{
   headers:{...(options.body?{"Content-Type":"application/json"}:{}),...(options.headers||{})},
   ...options
  });

  const data=await res.json().catch(()=>null);

  if(!res.ok)throw new Error(data?.message||data?.error||`Request failed (${res.status})`);

  return data;
 };

 const buildAppKey=value=>{
  return String(value||"")
   .trim()
   .toLowerCase()
   .replace(/[^a-z0-9\s-]/g,"")
   .replace(/\s+/g,"-")
   .replace(/-+/g,"-");
 };

 const handleChange=e=>{
  const {name,value,type,checked}=e.target;
  setFormData(prev=>({...prev,[name]:type==="checkbox"?checked:value}));
 };

 const handleNameBlur=()=>{
  if(initialData?._id||formData.appKey.trim())return;
  setFormData(prev=>({...prev,appKey:buildAppKey(prev.name)}));
 };

 const handleSubmit=async e=>{
  e.preventDefault();

  if(!formData.businessRef.trim()||!formData.name.trim()||!formData.appKey.trim()){
   setMessage({type:"danger",text:"Business, name and app key are required"});
   return;
  }

  try{
   setSaving(true);
   setMessage({type:"",text:""});

   const payload={
    businessRef:formData.businessRef.trim(),
    name:formData.name.trim(),
    appKey:buildAppKey(formData.appKey),
    isActive:!!formData.isActive
   };

   if(initialData?._id)await api(`/api/app-keys/${initialData._id}`,{method:"PUT",body:JSON.stringify(payload)});
   else await api("/api/app-keys",{method:"POST",body:JSON.stringify(payload)});

   if(onSaved)await onSaved();
   onHide();
  }catch(err){
   setMessage({type:"danger",text:err.message||"Failed to save app key"});
  }finally{
   setSaving(false);
  }
 };

 return(
  <Modal show={show} onHide={onHide} centered backdrop="static" size="lg">
   <Modal.Header closeButton>
    <Modal.Title>{initialData?._id?"Edit App Key":"Add App Key"}</Modal.Title>
   </Modal.Header>

   <Form onSubmit={handleSubmit}>
    <Modal.Body>
     {message.text?(
      <Alert variant={message.type||"info"} className="mb-3">{message.text}</Alert>
     ):null}

     <Row className="g-3">
      <Col md={6}>
       <Form.Group>
        <Form.Label>Business</Form.Label>
        <Form.Select name="businessRef" value={formData.businessRef} onChange={handleChange} required>
         <option value="">Select business</option>
         {businesses.map(business=>{
          const id=String(business?._id||business?.id||"");
          return(
           <option key={id} value={id}>
            {business?.legalName||business?.name||id}
           </option>
          );
         })}
        </Form.Select>
       </Form.Group>
      </Col>

      <Col md={6}>
       <Form.Group>
        <Form.Label>Name</Form.Label>
        <Form.Control name="name" value={formData.name} onChange={handleChange} onBlur={handleNameBlur} required />
       </Form.Group>
      </Col>

      <Col md={6}>
       <Form.Group>
        <Form.Label>App Key</Form.Label>
        <Form.Control name="appKey" value={formData.appKey} onChange={handleChange} placeholder="ex: home-tracker" required />
        <Form.Text muted>Use the app folder name, like home-tracker or bible-study.</Form.Text>
       </Form.Group>
      </Col>

      <Col xs={12}>
       <Form.Check type="switch" id="appKeyIsActive" name="isActive" label="Active" checked={formData.isActive} onChange={handleChange}/>
      </Col>
     </Row>
    </Modal.Body>

    <Modal.Footer>
     <Button type="button" variant="outline-secondary" onClick={onHide} disabled={saving}>Cancel</Button>
     <Button type="submit" disabled={saving}>
      {saving?<Spinner size="sm" animation="border"/>:null}
      <span className={saving?"ms-2":""}>{initialData?._id?"Update":"Create"}</span>
     </Button>
    </Modal.Footer>
   </Form>
  </Modal>
 );
}

