import {useNavigate,useParams} from "react-router-dom";

function StudyEntryForm(){

 const navigate=useNavigate();
 const {id}=useParams();
 const isEdit=Boolean(id);

 const [form,setForm]=useState({
  user:"",
  study:"",
  method:"",
  entryType:"",
  title:"",
  scripture:"",
  content:"",
  detail:"",
  tags:"",
  keywords:"",
  isImportant:false,
  isPinned:false,
  status:""
 });

 const [users,setUsers]=useState([]);
 const [studies,setStudies]=useState([]);
 const [methods,setMethods]=useState([]);
 const [entryTypes,setEntryTypes]=useState([]);
 const [statuses,setStatuses]=useState([]);

 const [loading,setLoading]=useState(false);
 const [loadingData,setLoadingData]=useState(true);
 const [error,setError]=useState("");
 const [success,setSuccess]=useState("");

 useEffect(()=>{
  let isMounted=true;

  const loadData=async()=>{
   try{
    setLoadingData(true);
    setError("");

    const requests=[
     fetch("/api/users"),
     fetch("/api/studies"),
     fetch("/api/methods"),
     fetch("/api/lookups/study-entry-types"),
     fetch("/api/lookups/statuses")
    ];

    if(isEdit){
     requests.push(fetch(`/api/studies/entries/${id}`));
    }

    const [
     usersRes,
     studiesRes,
     methodsRes,
     entryTypesRes,
     statusesRes,
     itemRes
    ]=await Promise.all(requests);

    const [
     usersData,
     studiesData,
     methodsData,
     entryTypesData,
     statusesData,
     itemData
    ]=await Promise.all([
     usersRes.json(),
     studiesRes.json(),
     methodsRes.json(),
     entryTypesRes.json(),
     statusesRes.json(),
     itemRes?itemRes.json():Promise.resolve(null)
    ]);

    if(!isMounted)return;

    setUsers(usersData.data||[]);
    setStudies(studiesData.data||[]);
    setMethods(methodsData.data||[]);
    setEntryTypes(entryTypesData.data||[]);
    setStatuses(statusesData.data||[]);

    if(isEdit&&itemData?.data){
     const item=itemData.data;

     setForm({
      user:item.user?._id||item.user||"",
      study:item.study?._id||item.study||"",
      method:item.method?._id||item.method||"",
      entryType:item.entryType?._id||item.entryType||"",
      title:item.title||"",
      scripture:item.scripture||"",
      content:item.content||"",
      detail:item.detail||"",
      tags:Array.isArray(item.tags)?item.tags.join(", "):"",
      keywords:Array.isArray(item.keywords)?item.keywords.join(", "):"",
      isImportant:Boolean(item.isImportant),
      isPinned:Boolean(item.isPinned),
      status:item.status?._id||item.status||""
     });
    }
   }
   catch(err){
    if(!isMounted)return;
    setError("Failed to load form data");
   }
   finally{
    if(isMounted)setLoadingData(false);
   }
  };

  loadData();

  return()=>{isMounted=false;};
 },[id,isEdit]);

 const handleChange=(e)=>{
  const {name,value,type,checked}=e.target;

  setForm(prev=>({
   ...prev,
   [name]:type==="checkbox"?checked:value
  }));
 };

 const handleSubmit=async(e)=>{
  e.preventDefault();

  try{
   setLoading(true);
   setError("");
   setSuccess("");

   const payload={
    ...form,
    method:form.method||null,
    status:form.status||null,
    tags:form.tags.split(",").map(tag=>tag.trim()).filter(Boolean),
    keywords:form.keywords.split(",").map(keyword=>keyword.trim()).filter(Boolean)
   };

   const res=await fetch(isEdit?`/api/studies/entries/${id}`:"/api/studies/entries",{
    method:isEdit?"PUT":"POST",
    headers:{
     "Content-Type":"application/json"
    },
    body:JSON.stringify(payload)
   });

   const data=await res.json();

   if(!res.ok){
    throw new Error(data.message||`Failed to ${isEdit?"update":"create"} study entry`);
   }

   setSuccess(`Study entry ${isEdit?"updated":"created"} successfully`);

   if(!isEdit){
    setForm({
     user:"",
     study:"",
     method:"",
     entryType:"",
     title:"",
     scripture:"",
     content:"",
     detail:"",
     tags:"",
     keywords:"",
     isImportant:false,
     isPinned:false,
     status:""
    });
   }
   else{
    setTimeout(()=>{
     navigate("/dashboard");
    },800);
   }
  }
  catch(err){
   setError(err.message);
  }
  finally{
   setLoading(false);
  }
 };

 if(loadingData){
  return(
   <div className="container py-4 text-center">
    <Spinner animation="border"/>
   </div>
  );
 }

