import {Form,Button,Card,Row,Col,Alert,Spinner} from "react-bootstrap";
import {useNavigate,useParams} from "react-router-dom";

function StudySessionForm(){

 const navigate=useNavigate();
 const {id}=useParams();
 const isEdit=Boolean(id);

 const [form,setForm]=useState({
  user:"",
  study:"",
  method:"",
  title:"",
  focus:"",
  location:"",
  notesExpected:"",
  scheduledFor:"",
  startedAt:"",
  endedAt:"",
  durationMinutes:0,
  status:"",
  summary:"",
  tags:""
 });

 const [users,setUsers]=useState([]);
 const [studies,setStudies]=useState([]);
 const [methods,setMethods]=useState([]);
 const [statuses,setStatuses]=useState([]);

 const [loading,setLoading]=useState(false);
 const [loadingData,setLoadingData]=useState(true);
 const [error,setError]=useState("");
 const [success,setSuccess]=useState("");

 useEffect(()=>{
  let isMounted=true;

  const formatDateTimeLocal=(value)=>{
   if(!value)return "";
   const date=new Date(value);
   if(Number.isNaN(date.getTime()))return "";
   const offset=date.getTimezoneOffset();
   const localDate=new Date(date.getTime()-offset*60000);
   return localDate.toISOString().slice(0,16);
  };

  const loadData=async()=>{
   try{
    setLoadingData(true);
    setError("");

    const requests=[
     fetch("/api/users"),
     fetch("/api/studies"),
     fetch("/api/methods"),
     fetch("/api/lookups/statuses")
    ];

    if(isEdit){
     requests.push(fetch(`/api/studies/sessions/${id}`));
    }

    const [
     usersRes,
     studiesRes,
     methodsRes,
     statusesRes,
     itemRes
    ]=await Promise.all(requests);

    const [
     usersData,
     studiesData,
     methodsData,
     statusesData,
     itemData
    ]=await Promise.all([
     usersRes.json(),
     studiesRes.json(),
     methodsRes.json(),
     statusesRes.json(),
     itemRes?itemRes.json():Promise.resolve(null)
    ]);

    if(!isMounted)return;

    setUsers(usersData.data||[]);
    setStudies(studiesData.data||[]);
    setMethods(methodsData.data||[]);
    setStatuses(statusesData.data||[]);

    if(isEdit&&itemData?.data){
     const item=itemData.data;

     setForm({
      user:item.user?._id||item.user||"",
      study:item.study?._id||item.study||"",
      method:item.method?._id||item.method||"",
      title:item.title||"",
      focus:item.focus||"",
      location:item.location||"",
      notesExpected:item.notesExpected||"",
      scheduledFor:formatDateTimeLocal(item.scheduledFor),
      startedAt:formatDateTimeLocal(item.startedAt),
      endedAt:formatDateTimeLocal(item.endedAt),
      durationMinutes:item.durationMinutes??0,
      status:item.status?._id||item.status||"",
      summary:item.summary||"",
      tags:Array.isArray(item.tags)?item.tags.join(", "):""
     });
    }
   }
   catch(err){
    if(!isMounted)return;
    setError("Failed to load form data");
   }
   finally{
    if(isMounted)setLoadingData(false);
   }
  };

  loadData();

  return()=>{isMounted=false;};
 },[id,isEdit]);

 const handleChange=(e)=>{
  const {name,value}=e.target;

  setForm((prev)=>({
   ...prev,
   [name]:value
  }));
 };

 const handleSubmit=async(e)=>{
  e.preventDefault();

  try{
   setLoading(true);
   setError("");
   setSuccess("");

   const payload={
    ...form,
    study:form.study||null,
    method:form.method||null,
    scheduledFor:form.scheduledFor||null,
    startedAt:form.startedAt||null,
    endedAt:form.endedAt||null,
    durationMinutes:Number(form.durationMinutes)||0,
    status:form.status||null,
    tags:form.tags.split(",").map((tag)=>tag.trim()).filter(Boolean)
   };

   const res=await fetch(isEdit?`/api/studies/sessions/${id}`:"/api/studies/sessions",{
    method:isEdit?"PUT":"POST",
